import{_ as e,o as t,c as o,a3 as n}from"./chunks/framework.B9qR_F1m.js";const _=JSON.parse('{"title":"会计学","description":"从会计要素与会计等式出发，覆盖借贷记账法、会计分录与财务报表勾稽。","frontmatter":{"title":"会计学","subject":"accounting","subjectLabel":"会计学","description":"从会计要素与会计等式出发，覆盖借贷记账法、会计分录与财务报表勾稽。"},"headers":[],"relativePath":"subjects/accounting/index.md","filePath":"subjects/accounting/index.md","lastUpdated":null}'),l={name:"subjects/accounting/index.md"};function r(i,a,s,u,c,d){return t(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="会计学" tabindex="-1">会计学 <a class="header-anchor" href="#会计学" aria-label="Permalink to &quot;会计学&quot;">​</a></h1><p>会计学部分按 <strong>基础会计 / 财务报表</strong> 两条线组织。核心目标是把&quot;每一笔业务&quot;准确翻译成 &quot;会计分录&quot;，再汇总成报表，因此笔记里每一节都配有完整的分录示例。</p><h2 id="分类导航" tabindex="-1">分类导航 <a class="header-anchor" href="#分类导航" aria-label="Permalink to &quot;分类导航&quot;">​</a></h2><h3 id="基础会计" tabindex="-1">基础会计 <a class="header-anchor" href="#基础会计" aria-label="Permalink to &quot;基础会计&quot;">​</a></h3><ul><li><a href="./fundamentals/accounting-elements">会计要素与会计等式（写作模板）</a> —— 六大要素与两大等式</li><li><a href="./fundamentals/journal-entries">借贷记账法与会计分录</a> —— 记账规则与常见业务分录</li></ul><h3 id="财务报表" tabindex="-1">财务报表 <a class="header-anchor" href="#财务报表" aria-label="Permalink to &quot;财务报表&quot;">​</a></h3><ul><li><a href="./statements/balance-sheet">资产负债表与利润表</a> —— 报表结构与项目之间的勾稽关系</li></ul><h2 id="写作约定" tabindex="-1">写作约定 <a class="header-anchor" href="#写作约定" aria-label="Permalink to &quot;写作约定&quot;">​</a></h2><ul><li>分录必须写成「<strong>借：科目 金额 / 贷：科目 金额</strong>」的形式，金额带单位 <code>元</code>；</li><li>涉及计算时列出算式，不直接给结果；</li><li>报表项目统一使用准则中的规范名称（如&quot;应收账款&quot;&quot;其他综合收益&quot;），不用口语简称。</li></ul><blockquote><p><strong>提示</strong>：会计分录里的数字较长，建议用代码块对齐书写，避免 Markdown 表格挤压换行。</p></blockquote>',10)])])}const q=e(l,[["render",r]]);export{_ as __pageData,q as default};
